// Cabeçalho padrão das mensagens do Comercial e do Operacional:
// Bolsão + cada cliente com nome, endereço, telefone e e-mail (coluna "Cliente" do Lists)
// Coluna "Cliente" = só o nome; Telefone, Email, Rua e Numero ficam em colunas próprias (uma linha por cliente).
// Itens antigos: "Nome, Rua e número, e-mail, Tel: ..." na própria coluna Cliente.
const linhasCliente = f => {
  const col = v => String(v || '').split('\n').map(s => s.trim());
  const nomes = col(f.Cliente || f.Bolsao).filter(Boolean);
  if (!(f.Telefone || f.Email || f.Rua || f.Numero)) return nomes;
  return nomes.map((nome, i) => {
    const partes = [nome.replace(/,/g, ' '), [col(f.Rua)[i], col(f.Numero)[i]].filter(Boolean).join(' ').replace(/,/g, ' '), col(f.Email)[i]].filter(Boolean);
    if (col(f.Telefone)[i]) partes.push('Tel: ' + col(f.Telefone)[i]);
    return partes.join(', ');
  });
};
const cabecalhoCliente = f => {
  const linhas = linhasCliente(f);
  const blocos = linhas.map(l => {
    const partes = l.split(',').map(s => s.trim()).filter(Boolean);
    const nome = (partes.shift() || '').split(' — ')[0].trim();
    const email = (l.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/) || [])[0];
    const tel = (l.match(/Tel\.?:\s*([^,]+)/i) || [])[1];
    const endereco = partes.filter(s => !s.includes('@') && !/^Tel\.?:/i.test(s)).join(', ');
    return `👤 *Cliente:* ${nome || 'Não informado'}\n📍 *Endereço:* ${endereco || 'Não informado'}\n📞 *Telefone:* ${tel ? tel.trim() : 'Não informado'}\n📧 *E-mail:* ${email || 'Não informado'}`;
  });
  if (!blocos.length) blocos.push('👤 *Cliente:* Não informado\n📍 *Endereço:* Não informado\n📞 *Telefone:* Não informado\n📧 *E-mail:* Não informado');
  return `🏘️ *Bolsão:* ${f.Title || 'Não informado'}\n\n` + blocos.join('\n\n');
};

// Monta um lembrete para cada etapa ainda não confirmada como realizada
const P = {
  fin: 'inclusao:financeiro:poll:',
  cad: 'inclusao:cadastros:poll:',
  com: 'inclusao:comercial:poll:',
  ope: 'inclusao:operacional:poll:'
};

const ETAPAS = {
  finCadastro:  { area: 'FINANCEIRO', prefixo: P.fin, etapa: 'Cadastro Financeiro',
                  acao: 'Realizar os cadastros financeiros do novo cliente.',
                  opcoes: ['✅ Cadastro realizado', '⚠️ Pendente'] },
  finFormEnvio: { area: 'FINANCEIRO', prefixo: P.fin, etapa: 'Formulario Financeiro',
                  acao: 'Enviar o formulário de cadastro ao cliente.',
                  opcoes: ['✅ Formulário enviado', '⚠️ Pendente'] },
  finFormRetorno: { area: 'FINANCEIRO', prefixo: P.fin, etapa: 'Retorno Formulario Financeiro',
                  acao: 'Confirmar o recebimento do formulário preenchido pelo cliente.',
                  opcoes: ['✅ Formulário recebido', '⚠️ Pendente'] },
  cadastros:    { area: 'CADASTROS', prefixo: P.cad, etapa: 'Cadastros',
                  acao: 'Cadastrar no FINDME, MONUV e SIGMA.',
                  opcoes: ['✅ Cadastros concluídos', '⚠️ Pendente'] },
  comKit:       { area: 'COMERCIAL', prefixo: P.com, etapa: 'Kit Boas-Vindas Comercial',
                  acao: 'Enviar o Kit de Boas-Vindas ao cliente.',
                  opcoes: ['✅ Kit de Boas-Vindas enviado', '⚠️ Pendente'] },
  comGrupo:     { area: 'COMERCIAL', prefixo: P.com, etapa: 'Inclusao Grupo Comercial',
                  acao: 'Incluir o cliente no grupo de comunicação.',
                  opcoes: ['✅ Inclusão no grupo realizada', '⚠️ Pendente'] },
  opeContato:   { area: 'OPERACIONAL', prefixo: P.ope, etapa: 'Contato Cliente Operacional',
                  acao: 'Entrar em contato com o novo cliente.',
                  opcoes: ['✅ Contato realizado', '⚠️ Pendente'] },
  opePlaca:     { area: 'OPERACIONAL', prefixo: P.ope, etapa: 'Instalacao Placa Operacional',
                  acao: 'Realizar a instalação da placa de identificação ASTER no cliente.',
                  opcoes: ['✅ Placa instalada', '⚠️ Pendente'] },
  opeEquipe:    { area: 'OPERACIONAL', prefixo: P.ope, etapa: 'Orientacao Equipe Operacional',
                  acao: 'Orientar a equipe operacional sobre a entrada do novo cliente.',
                  opcoes: ['✅ Equipe orientada', '⚠️ Pendente'] }
};

const etapaFinanceiro = s => ({
  'Aguardando Cadastro': 'finCadastro',
  'Cadastro Realizado': 'finFormEnvio',
  'Formulario Enviado': 'finFormRetorno', 'Aguardando Formulario': 'finFormRetorno',
  'Formulario Recebido': 'finFormRetorno'
}[s] || null);

const etapaComercial = s =>
  ({ 'Aguardando Comercial': 'comKit', 'Kit de Boas-Vindas Enviado': 'comGrupo', 'Aguardando Inclusao no Grupo': 'comGrupo' }[s] || null);

const etapaOperacional = s =>
  ({ 'Aguardando Operacional': 'opeContato', 'Contato com Cliente Realizado': 'opePlaca', 'Placa Instalada': 'opeEquipe' }[s] || null);

const saida = [];

for (const item of $input.all()) {
  const f = item.json.fields || {};
  if (!item.json.id) continue;
  const cliente = f.Title || 'Não informado';
  const chaves = [];

  if (f.StatusAutomacao === 'Aguardando Financeiro e Cadastros') {
    // Financeiro: notificado por e-mail (WF 2), com reenvio automático
    if (f.CadastrosStatus !== 'Concluido') chaves.push('cadastros');
  }

  if (f.StatusAutomacao === 'Aguardando Comercial e Operacional') {
    chaves.push(etapaComercial(f.ComercialStatus));
    chaves.push(etapaOperacional(f.OperacionalStatus));
  }

  for (const k of chaves.filter(Boolean)) {
    const e = ETAPAS[k];
    saida.push({
      json: {
        itemId: item.json.id,
        cliente,
        prefixo: e.prefixo,
        etapa: e.etapa,
        opcoes: e.opcoes,
        mensagem: `🔔 *LEMBRETE – ${e.area}*\n\n${['CADASTROS', 'COMERCIAL', 'OPERACIONAL'].includes(e.area) ? cabecalhoCliente(f) : `🏢 *Cliente:* ${cliente}`}\n\n📌 *Pendência:*\n${e.acao}\n\nApós concluir, selecione uma opção abaixo.`
      }
    });
  }
}

return saida;

